// CI history secret-scan repair check (inside the Dev Container, repo root, full local history).
// 1) Same work set: the (path, blob) pairs the repaired scan reads equal the distinct pairs the previous scan read.
// 2) Same verdict and timing: previous (e2fe87d) and repaired sourceSecretScan on the real repository, both
//    with no known secrets and with a known value that occurs only in history (must be rejected by both, same findings).
import { execFileSync, spawnSync } from 'node:child_process';
import { mkdtempSync, writeFileSync, rmSync } from 'node:fs';
import { tmpdir } from 'node:os';
import { join, resolve } from 'node:path';
const root = process.cwd(), dir = mkdtempSync(join(tmpdir(), 'audit-scan-'));
const out = {};
try {
  const previous = execFileSync('git', ['show', 'e2fe87d:scripts/ci/security.mjs'], { encoding: 'utf8' })
    .replace("'../documentation-lib.mjs'", JSON.stringify(resolve(root, 'scripts/documentation-lib.mjs')))
    .replace("'../engine/vendor.mjs'", JSON.stringify(resolve(root, 'scripts/engine/vendor.mjs')))
    .replace("new URL('./policy.json',import.meta.url)", JSON.stringify(resolve(root, 'scripts/ci/policy.json')));
  writeFileSync(join(dir, 'previous.mjs'), previous);
  const prev = await import(join(dir, 'previous.mjs')), next = await import(resolve(root, 'scripts/ci/security.mjs'));
  // 1) work set
  const revs = execFileSync('git', ['rev-list', '--all'], { encoding: 'utf8' }).trim().split('\n');
  let reads = 0; const pairs = new Set();
  for (const r of revs) for (const e of execFileSync('git', ['ls-tree', '-r', '-z', r], { encoding: 'utf8', maxBuffer: 5e6 }).split('\0').filter(Boolean)) { const [m, p] = e.split('\t'); reads++; pairs.add(m.split(' ')[2] + '\0' + p); }
  out.workSet = { revisions: revs.length, previousBlobReads: reads, repairedBlobReads: pairs.size };
  // a value present only in history: a line from an older AGENTS.md/README.md that no file at HEAD contains
  let historical;
  for (const r of revs.slice(Math.floor(revs.length / 2)).reverse()) {
    for (const file of ['AGENTS.md', 'README.md', 'docs/README.md']) {
      let text; try { text = execFileSync('git', ['show', r + ':' + file], { encoding: 'utf8', stdio: ['ignore', 'pipe', 'ignore'] }); } catch { continue; }
      for (const line of text.split('\n').map(l => l.trim()).filter(l => l.length >= 24 && l.length <= 200 && !l.includes('"'))) {
        if (spawnSync('git', ['grep', '-qF', line, 'HEAD']).status === 1) { historical = line; break; }
      }
      if (historical) break;
    }
    if (historical) break;
  }
  const runScan = (mod, known) => { const t0 = performance.now(); try { mod.sourceSecretScan(root, known); return { result: 'passed', ms: Math.round(performance.now() - t0) }; } catch (e) { return { result: 'rejected', ms: Math.round(performance.now() - t0), findings: e.message.replace(/^Secret scan rejected safe findings: /, '') }; } };
  out.cleanPrevious = runScan(prev, []); out.cleanRepaired = runScan(next, []);
  out.historyOnlyValueFound = Boolean(historical);
  if (historical) { out.knownHistoricalPrevious = runScan(prev, [historical]); out.knownHistoricalRepaired = runScan(next, [historical]); out.sameFindings = out.knownHistoricalPrevious.findings === out.knownHistoricalRepaired.findings; }
} finally { rmSync(dir, { recursive: true, force: true }); }
console.log(JSON.stringify(out, null, 1));
const ok = out.cleanPrevious.result === 'passed' && out.cleanRepaired.result === 'passed' && out.historyOnlyValueFound && out.knownHistoricalPrevious.result === 'rejected' && out.sameFindings && out.workSet.repairedBlobReads <= out.workSet.previousBlobReads;
if (!ok) process.exitCode = 1;
